  "SHIELD linear team labels --team <key-or-id> --workspace <workspaceId> --json",
  "SHIELD linear team members --team <key-or-id> --workspace <workspaceId> --json",
  "SHIELD linear project list --query <project-name> --workspace <workspaceId> --json",
